-- Apply after 007_archive_level_one.sql.
begin;

insert into public.archive_content(slug,title,body,registration_required,required_archive_level,published) values
('morgeus','Моргеус',jsonb_build_object(
 'title','Моргеус','subtitle','Архивное досье верховного мага','type','Досье','stat',jsonb_build_object('value','170 лет','title','Это не легенда и не ошибка','text','Столь долгую жизнь Моргеусу обеспечивает его уникальный нейронекс.'),
 'sections',jsonb_build_array(
  jsonb_build_object('eyebrow','I · Архивная сводка','title','Верховный маг Фраустера','paragraphs',jsonb_build_array('Моргеус — верховный маг Фраустера и один из сильнейших людей за всю историю мира.')),
  jsonb_build_object('eyebrow','II · Возраст','title','Жизнь длиной около 170 лет','paragraphs',jsonb_build_array('Столь долгую жизнь ему обеспечивает его уникальный нейронекс. В отличие от обычных людей, его нейронекс аномально развит и тесно связан с системами снабжения мозга кислородом и кровью.','Благодаря этому организм Моргеуса стареет значительно медленнее.')),
  jsonb_build_object('eyebrow','III · Нейронекс','title','Несколько стихий','paragraphs',jsonb_build_array('Моргеус обладает крайне редким комбинированным нейронексом, который позволяет использовать сразу несколько стихий.','Подобные случаи встречаются чрезвычайно редко. Именно эта особенность сделала его одним из самых могущественных магов в истории.')),
  jsonb_build_object('eyebrow','IV · Посох стихий','title','Не источник силы','paragraphs',jsonb_build_array('Большинство людей считают, что Посох стихий усиливает Моргеуса. На самом деле всё наоборот.','Посох был создан для того, чтобы ограничивать поступление ЭМИ в нейронекс Моргеуса. Без этого ограничения количество энергии, проходящее через его организм, может стать опасным для самого Моргеуса и для окружающих.'),'emphasis','Посох стихий является не источником силы, а её ограничителем.','tone','revelation'),
  jsonb_build_object('eyebrow','V · Великая война','title','Снятые ограничения','paragraphs',jsonb_build_array('Во время Великой войны Моргеус лично участвовал в боях против драконов. В одном из сражений он был вынужден отказаться от ограничений Посоха стихий и использовать свою силу в полном объёме.','Ему удалось уничтожить нескольких драконов и спасти короля Филка. Однако цена оказалась огромной.')),
  jsonb_build_object('eyebrow','VI · Рондерград','title','Город, уничтоженный силой мага','paragraphs',jsonb_build_array('В результате применения полной силы Моргеуса был уничтожен Рондерград. Это один из самых тяжёлых эпизодов его прошлого.'),'tone','warning'),
  jsonb_build_object('eyebrow','VII · Реальный уровень силы','title','Исключение из известных правил','paragraphs',jsonb_build_array('Моргеус считается сильнейшим человеком своего времени. Его мощь была настолько велика, что он смог сравняться по силе с Дариусом в третьей фазе.','Для человека подобное считается практически невозможным достижением. Докаины изначально являются более сильными существами, поэтому человек, способный достичь подобного уровня, является исключением из известных правил.')),
  jsonb_build_object('eyebrow','VIII · Связь с Гасом','title','Уважение, пережившее войну','paragraphs',jsonb_build_array('Во время Великой войны с драконами началась дружба между Моргеусом и будущим генералом Гасом.','Тогда Моргеус находился рядом с королём Филком и участвовал в важнейших событиях войны. Именно в тот период между Моргеусом и Гасом сформировалось взаимное уважение, которое сохранилось на долгие годы.'))
 ),'contrast',jsonb_build_object('common','Посох усиливает Моргеуса.','archive','Посох ограничивает Моргеуса.'),'closing','Сила Моргеуса измеряется не только тем, что он способен совершить, но и тем, что вынужден постоянно сдерживать.','related',jsonb_build_object('title','Вражда Фраустера и Майзервина','href','Archive_Frauster_Maizervin.html')
),true,1,true),
('frauster-maizervin-feud','Вражда Фраустера и Майзервина',jsonb_build_object(
 'title','Вражда Фраустера и Майзервина','subtitle','Архивная хроника событий Великой войны','type','Исторический документ',
 'sections',jsonb_build_array(
  jsonb_build_object('eyebrow','I · Историческая справка','title','Помощь против общей угрозы','paragraphs',jsonb_build_array('Во время Великой войны с драконами король Филк отправил армию Фраустера на помощь Майзервину. Командование армией было поручено Моргеусу.','Целью была защита Майзергарда. Фраустерская армия прибыла на территорию Майзервина для борьбы с общей угрозой.')),
  jsonb_build_object('eyebrow','II · До нападения','title','Суровый климат','paragraphs',jsonb_build_array('Проблемы начались ещё до нападения драконов. Климат Майзервина крайне суровый. Несмотря на это, воинам Фраустера не стали выдавать тёплую одежду.','Моргеусу пришлось решить проблему самостоятельно. Он использовал магию огня, чтобы согреть свою армию.'),'tone','warm'),
  jsonb_build_object('eyebrow','III · Нападение','title','Информация, которой не было','paragraphs',jsonb_build_array('Затем драконы напали на Майзергард. Армия Моргеуса вступила в бой, защищая город.','Моргеус не знал, что на стороне Майзервина находится ледяной дракон Нирафат и что он будет участвовать в сражении на стороне защитников.'),'tone','cold'),
  jsonb_build_object('eyebrow','IV · Нирафат','title','Священный защитник Майзервина','paragraphs',jsonb_build_array('Нирафат был не просто союзным драконом. Он являлся священным драконом Майзервина и на протяжении многих лет оберегал государство.','Во время сражения Моргеус, не знавший о роли Нирафата, принял его за одного из вражеских драконов. Моргеус убил Нирафата.'),'tone','cold'),
  jsonb_build_object('eyebrow','V · Победа у Майзергарда','title','Спасение и непоправимая потеря','paragraphs',jsonb_build_array('После гибели Нирафата Моргеус продолжил сражение. Ему удалось отбить Майзергард от остальных драконов.')),
  jsonb_build_object('eyebrow','VI · Реакция Галдвина','title','Подозрение короля','paragraphs',jsonb_build_array('Король Майзервина Галдвин сильно разгневался после гибели Нирафата. Он не воспринял произошедшее как обычную ошибку или случайность.','Галдвин посчитал, что король Филк мог специально дать Моргеусу такое задание. Это было подозрение Галдвина, а не установленная истина.','После произошедшего Галдвин прогнал Моргеуса и фраустерскую армию со своей земли.'),'tone','cold'),
  jsonb_build_object('eyebrow','VII · Последствия','title','Контакты без доверия','paragraphs',jsonb_build_array('Именно эти события стали причиной длительной вражды между Фраустером и Майзервином. Однако государства не прекратили взаимодействовать полностью.','С тех пор они поддерживали только необходимые взаимовыгодные торговые соглашения. Экономическая необходимость сохранила контакты, но доверие не восстановилось, вражда не утихла, а военное напряжение никуда не исчезло.'))
 ),'timeline',jsonb_build_array('Филк отправляет помощь','Фраустерская армия прибывает в Майзервин','Воинам не предоставляют тёплую одежду','Моргеус согревает их магией','Начинается нападение драконов','Моргеус не знает о Нирафате','Моргеус убивает Нирафата','Моргеус отбивает Майзергард','Галдвин считает убийство намеренным','Фраустерцев изгоняют','Между государствами начинается длительная вражда'),'closing','Моргеус спас Майзергард. И одновременно Моргеус убил священного защитника Майзервина.','related',jsonb_build_object('title','Моргеус','href','Archive_Morgeus.html')
),true,1,true)
on conflict(slug) do update set title=excluded.title,body=excluded.body,registration_required=true,required_archive_level=1,published=true,updated_at=now();

commit;
